const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define the eastern tropical Pacific region (approximate bounding box)
  // [minLongitude, minLatitude, maxLongitude, maxLatitude]
  const region = ee.Geometry.Rectangle([-160, -10, -80, 10]); // Roughly 160W to 80W, 10S to 10N

  // Target period: November 2021
  const november2021Start = '2021-11-01';
  const november2021End = '2021-11-30';

  // Long-term average period: November, 1982-2020 (excluding 2021)
  const longTermStartYear = 1982;
  const longTermEndYear = 2020;

  // 2. Data Acquisition
  const oisst = ee.ImageCollection('NOAA/AVHRR_OISST/V2');

  // Filter for November 2021
  const november2021Collection = oisst.filterDate(november2021Start, november2021End)
    .filterBounds(region);

  // Check if target collection is empty
  if (november2021Collection.size().getInfo() === 0) {
    console.log("No OISST data found for November 2021.");
    console.log("C1");
    return;
  }

  // Filter for all Novembers in the long-term period
  let longTermNovemberCollection = ee.ImageCollection([]);
  for (let year = longTermStartYear; year <= longTermEndYear; year++) {
    const start = ee.Date.fromYMD(year, 11, 1);
    const end = ee.Date.fromYMD(year, 11, 30); // Note: Dec 1 for filterDate exclusive end
    const yearNovember = oisst.filterDate(start, end).filterBounds(region);
    longTermNovemberCollection = longTermNovemberCollection.merge(yearNovember);
  }

  // Check if long-term collection is empty
  if (longTermNovemberCollection.size().getInfo() === 0) {
    console.log(`No OISST data found for long-term Novembers (${longTermStartYear}-${longTermEndYear}).`);
    console.log("C1");
    return;
  }

  // 3. Processing
  // Calculate mean SST for November 2021
  const meanSST2021 = november2021Collection.select('sst').mean();

  // Calculate mean SST for long-term Novembers
  const meanSSTLongTerm = longTermNovemberCollection.select('sst').mean();

  // Define reduction parameters
  const reducer = ee.Reducer.mean();
  const scale = 5000; // OISST resolution is ~0.25 degrees, so 5km is appropriate for a large region.
  const maxPixels = 1e9;

  // Reduce regions to get scalar values
  const sst2021Val = meanSST2021.reduceRegion({
    reducer: reducer,
    geometry: region,
    scale: scale,
    maxPixels: maxPixels
  }).get('sst');

  const sstLongTermVal = meanSSTLongTerm.reduceRegion({
    reducer: reducer,
    geometry: region,
    scale: scale,
    maxPixels: maxPixels
  }).get('sst');

  // Get info to client-side
  const sst2021 = await ee.data.computeValue(sst2021Val);
  const sstLongTerm = await ee.data.computeValue(sstLongTermVal);

  // 4. Validation & Final Answer
  if (sst2021 === null || isNaN(sst2021) || sstLongTerm === null || isNaN(sstLongTerm)) {
    console.log("Calculated SST values are null or NaN, indicating a calculation failure.");
    console.log(`2021 SST: ${sst2021}, Long-term SST: ${sstLongTerm}`);
    console.log("C3");
    return;
  }

  // Check pixel counts (proxy for C2, though less critical for OISST)
  // For OISST, if the mean value is not null, it implies pixels were present.
  // We can't directly check reduceRegion's pixel count from the result,
  // but if the values are not null, we assume valid pixels.

  const diffSST = sst2021 - sstLongTerm; // 2021 minus long-term average

  console.log(`November 2021 SST: ${sst2021.toFixed(2)} °C`);
  console.log(`Long-term Nov SST (${longTermStartYear}-${longTermEndYear}): ${sstLongTerm.toFixed(2)} °C`);
  console.log(`Difference (2021 - Long-term): ${diffSST.toFixed(2)} °C`);

  // A threshold for "decrease" might be considered, but for strict comparison,
  // any negative difference means a decrease.
  const threshold = -0.01; // Consider a very small negative value to account for floating point errors if exact zero is not expected.

  if (diffSST < threshold) { // If 2021 SST is noticeably lower than long-term
    console.log("A"); // Yes, it decreased
  } else {
    console.log("B"); // No, it did not decrease (either increased or stayed roughly the same)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
